INSERT INTO `areatable_dbc` (`ID`, `ContinentID`, `ParentAreaID`, `AreaBit`, `Flags`, `SoundProviderPref`, `SoundProviderPrefUnderwater`, `AmbienceID`, `ZoneMusic`, `IntroSound`, `ExplorationLevel`, `AreaName_Lang_enUS`, `AreaName_Lang_enGB`, `AreaName_Lang_koKR`, `AreaName_Lang_frFR`, `AreaName_Lang_deDE`, `AreaName_Lang_enCN`, `AreaName_Lang_zhCN`, `AreaName_Lang_enTW`, `AreaName_Lang_zhTW`, `AreaName_Lang_esES`, `AreaName_Lang_esMX`, `AreaName_Lang_ruRU`, `AreaName_Lang_ptPT`, `AreaName_Lang_ptBR`, `AreaName_Lang_itIT`, `AreaName_Lang_Unk`, `AreaName_Lang_Mask`, `FactionGroupMask`, `LiquidTypeID_1`, `LiquidTypeID_2`, `LiquidTypeID_3`, `LiquidTypeID_4`, `MinElevation`, `Ambient_Multiplier`, `Lightid`) VALUES
(5114, 1, 15, 3796, 1073741888, 0, 11, 40, 191, 0, 36, 'Westhaven Hollow', 'Westhaven Hollow', 'Westhaven Hollow', 'Westhaven Hollow', 'Westhaven Hollow', 'Westhaven Hollow', 'Westhaven Hollow', 'Westhaven Hollow', 'Westhaven Hollow', 'Westhaven Hollow', 'Westhaven Hollow', 'Westhaven Hollow', 'Westhaven Hollow', 'Westhaven Hollow', 'Westhaven Hollow', 'Westhaven Hollow', 16712190, 0, 0, 0, 0, 0, -500.0, 0.0, 0);
INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES
(5088, 100, 0, 'I am Falgran Hastil, scout of Theramore. Why did you call for this meeting?', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66478'),
(61056, 0, 0, 'We saw you investigate the inn. We wanted to assure you it is not the Horde\'s doing.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66479'),
(5088, 101, 0, 'We found this shield strapped to the wall of the inn. Do you have any recollection of this object?', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66480'),
(61056, 1, 0, 'Let me see.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66481'),
(61056, 2, 0, 'Kagoro investigates the shield thoroughly.', 16, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66482'),
(61056, 3, 0, 'By the ancestors. Yes, I know this shield. It belonged to Wattapo, a Tauren warrior who once lived in the Brackenwall Village. He died a long time ago.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66483'),
(5088, 102, 0, 'Do you know how it could\'ve ended up in the inn? We found his grave. It was recently disturbed.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66484'),
(61056, 4, 0, 'To disturb the grave of a fallen warrior I assure you, I know nothing of this.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66485'),
(5088, 103, 0, 'It seems like someone wanted to make us blame you for the burning of the inn.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66486'),
(61056, 5, 0, 'Indeed. Have you found anything else in the investigation?', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66487'),
(5088, 104, 0, 'Yes, quillboar footprints...', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66488'),
(61056, 6, 0, 'False lead.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66489'),
(5088, 105, 0, 'I see you did some work too.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66490'),
(61056, 7, 0, 'Kagoro nods.', 16, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66491'),
(5088, 106, 0, 'And the badge of one of the deserters. Paval Reethe. We couldn\'t find Reethe, though. Have you seen him, by any chance?', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66492'),
(61056, 8, 0, 'This is... a delicate matter, and the actual reason I called for the meeting. Paval Reethe is dead.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66493'),
(5088, 107, 0, 'He was a deserter. While I still would\'ve preferred to arrest him and allow for a just trial, I understand that you killed him. We do not blame you.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66494'),
(61056, 9, 0, 'If it only was that simple. We knew he was connected to the burning of the inn, and we wanted to investigate him. Before he could talk... we were attacked. By Theramore soldiers. One of them bore the name Caldwell.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66495'),
(5088, 108, 0, 'Attacked? Unprovoked, by Theramore soldiers? I swear to the Light, orc. If you are lying...', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66496'),
(61056, 10, 0, 'I swear upon my ancestors and my Warchief. They killed him in cold blood. Quick arrow pierced his heart. We also barely made it out alive.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66497'),
(5088, 109, 0, 'Theramore soldiers would never... We shall investigate this. But if we find out that your words aren\'t true...', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66498'),
(61056, 11, 0, 'I am sorry for the loss of your comrades. While you investigate this, we shall follow another lead we have. Black Dragonflight.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66499'),
(5088, 110, 0, 'And we will investigate in Theramore. But be warned, orc. Your story doesn\'t add up.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66500'),
(61056, 12, 0, 'Let\'s meet here once we know more. I hope you will find truth in your city of stones.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66501'),
(5088, 111, 0, 'Kagoro! We are ready.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66502'),
(61056, 13, 0, 'Falgran.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66503'),
(5088, 112, 0, 'Kagoro, on the behalf of the Alliance and the City of Theramore, I would like to apologize for not believing you and my false accusations. We are now certain that the deserters burned the inn.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66504'),
(61056, 14, 0, 'I am relieved to hear it. Our investigation of Black Dragons yielded no results. But how did you learn of the truth?', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66505'),
(5088, 113, 0, 'Through the power of magic, of course. Arts of Divination. We communed with the spirit of Paval Reethe.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66506'),
(61056, 15, 0, 'Extraordinary. Incredible sorcery, as always. But... why? Why did they burn the inn?', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66507'),
(5088, 114, 0, 'Well. This is where it gets a bit complicated. The deserters were regular patrons of the inn. In their drunken state, they confessed... something to the innkeeper. In fear of the information reaching Theramore, they preferred to kill him and leave false evidence.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66508'),
(61056, 16, 0, 'The shield... Yes, it makes sense.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66509'),
(5088, 115, 0, 'Paval Reethe wanted to stop them. He may have been a deserter, but he had some of his honor still left in his heart.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66510'),
(61056, 17, 0, 'That\'s why they left him in the swamp. But, what was the information that was so precious to the deserters?', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66511'),
(5088, 116, 0, 'About this, we are not sure. Something about the Vengeful Mariner, their rumored true leader. Have you heard about him?', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66512'),
(61056, 18, 0, 'Vengeful Mariner... The Ogres speak of a haunted sailor terrorizing the shores, but I doubt it\'s connected.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66513'),
(5088, 117, 0, 'We will soon bring justice to the deserters for their crimes, thank you for your information Kagoro, the horde has helped plenty in these lands.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66514'),
(61056, 19, 0, 'We believe in justice the same way you alliance do, go with honor friend.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66515'),
(5088, 118, 0, 'We should report to Captain Garran Vimes and let him know our discoveries.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66516'),
(61056, 20, 0, 'I am Kagoro. We saw you investigate the inn. We wanted to assure you it is not the Horde\'s doing.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66529'),
(5088, 119, 0, 'We found this shield strapped to the wall of the inn. Do you have any recollection of this object?', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66530'),
